{
  "category_edits": [
    {
      "category": "training_strategy",
      "rationale": "Replace validation-triggered learning-rate reductions with epoch-level cosine decay to 10% of the initial rate. Preserve Adam, base learning rate, batch size, dropout, weight decay, early stopping, and the GRU model.",
      "edits": [
        {
          "find": "NUM_EPOCHS    = int(os.environ.get(\"GRU4REC_EPOCHS\", \"200\"))",
          "replace": "NUM_EPOCHS    = min(200, int(os.environ.get(\"GRU4REC_EPOCHS\", \"200\")))"
        },
        {
          "find": "    scheduler = torch.optim.lr_scheduler.ReduceLROnPlateau(\n        optimizer, mode=\"max\", factor=0.5, patience=1,\n        threshold=0.0, threshold_mode=\"abs\", min_lr=LR * 0.125\n    )",
          "replace": "    scheduler = torch.optim.lr_scheduler.CosineAnnealingLR(\n        optimizer, T_max=max(NUM_EPOCHS, 1), eta_min=LR * 0.1\n    )"
        },
        {
          "find": "        avg_loss = total_loss / max(NUM_BATCHES, 1)\n        if epoch % EVAL_EVERY == 0 or epoch == NUM_EPOCHS:",
          "replace": "        avg_loss = total_loss / max(NUM_BATCHES, 1)\n        scheduler.step()\n        if epoch % EVAL_EVERY == 0 or epoch == NUM_EPOCHS:"
        },
        {
          "find": "            hr10 = val_m[\"HR@10\"]\n            scheduler.step(hr10)",
          "replace": "            hr10 = val_m[\"HR@10\"]"
        }
      ]
    }
  ],
  "change_summary": "Apply epoch-level cosine learning-rate decay across all four category models, enforce the 200-epoch cap, and preserve architecture, loss, routing, and checkpoint selection."
}
